<?php
namespace App\Services\Media;
use App\Contracts\ProtectedMediaStorage;use App\Models\{MediaAsset,MediaVariant,StorageLedgerEntry,User};use App\Support\MediaQuality;use Illuminate\Support\Str;use RuntimeException;
class MediaVariantProcessor{
 public function __construct(private ProtectedMediaStorage$storage){}
 public function process(MediaAsset$asset):void{$version=(int)config('media.processing.version',2);$original=$asset->variants()->where('variant_type','original')->where('state','ready')->firstOrFail();$bytes=$this->read($original->object_key);$image=@imagecreatefromstring($bytes);if(!$image)throw new RuntimeException('This image could not be processed.');if(imagesx($image)*imagesy($image)>(int)config('media.processing.max_decoded_pixels',80000000)){imagedestroy($image);throw new RuntimeException('This photo exceeds the allowed processing limits.');}$oriented=$this->orient($image,(int)$asset->orientation);if($oriented!==$image)imagedestroy($image);$image=$oriented;$profile=$this->profile($asset->quality_mode);$fingerprint=$this->fingerprint($asset->quality_mode,$profile,$version);$variants=[['optimized',$profile['max_edge'],$profile['quality'],$profile['min_quality'],$profile['target_bytes']],['viewer',(int)config('media.processing.viewer.max_edge',2560),(int)config('media.processing.viewer.quality',92),(int)config('media.processing.viewer.min_quality',88),(int)config('media.processing.viewer.target_bytes',2097152)],['grid',(int)config('media.processing.grid.max_edge',1200),(int)config('media.processing.grid.quality',88),(int)config('media.processing.grid.min_quality',84),(int)config('media.processing.grid.target_bytes',524288)],['thumbnail',(int)config('media.processing.thumbnail.max_edge',480),(int)config('media.processing.thumbnail.quality',84),(int)config('media.processing.thumbnail.min_quality',80),(int)config('media.processing.thumbnail.target_bytes',163840)]];foreach($variants as[$type,$max,$quality,$floor,$target])$this->generate($asset,$image,$original->mime_type,$type,$max,$quality,$floor,$target,$version,$fingerprint);$master=$asset->variant('optimized');$asset->update(['state'=>'completed','processing_profile'=>$asset->quality_mode,'processing_version'=>$version,'encoder'=>'gd-'.GD_VERSION,'width'=>imagesx($image),'height'=>imagesy($image),'stored_master_bytes'=>$master?->size_bytes]);imagedestroy($image);}
 private function generate(MediaAsset$asset,$source,string$sourceMime,string$type,int$max,int$preferred,int$minimum,int$targetBytes,int$version,string$fingerprint):void{if($asset->variants()->where('variant_type',$type)->where('version',$version)->where('profile_fingerprint',$fingerprint)->where('state','ready')->exists())return;[$image,$width,$height]=$this->resize($source,$max,$sourceMime);[$output,$mime,$extension,$quality]=$this->adaptive($image,$sourceMime,$preferred,$minimum,$targetBytes);imagedestroy($image);$check=@imagecreatefromstring($output);if(!$check||imagesx($check)!==$width||imagesy($check)!==$height)throw new RuntimeException('Generated media could not be verified.');imagedestroy($check);$key=config('media.prefixes.'.($type==='thumbnail'?'thumbnails':'optimized')).'/groups/'.$asset->group_id.'/'.$type.'-'.Str::uuid().'.'.$extension;$this->storage->put($key,$output,$mime);MediaVariant::updateOrCreate(['media_asset_id'=>$asset->id,'variant_type'=>$type,'version'=>$version],['storage_disk'=>$this->storage->disk(),'object_key'=>$key,'mime_type'=>$mime,'size_bytes'=>strlen($output),'checksum_sha256'=>hash('sha256',$output),'width'=>$width,'height'=>$height,'state'=>'ready','error'=>null,'encoder_quality'=>$quality,'profile_fingerprint'=>$fingerprint]);$ledger=StorageLedgerEntry::firstOrCreate(['idempotency_key'=>'variant-'.$asset->uuid.'-'.$type.'-v'.$version],['owner_id'=>$asset->owner_id,'group_id'=>$asset->group_id,'media_asset_id'=>$asset->id,'event_type'=>'variant_created','byte_delta'=>strlen($output)]);if($ledger->wasRecentlyCreated)User::whereKey($asset->owner_id)->increment('storage_used',strlen($output));}
 private function adaptive($image,string$mime,int$preferred,int$minimum,int$target):array{if($mime==='image/png'){[$bytes,$outMime,$extension]=$this->encode($image,$mime,$preferred);return[$bytes,$outMime,$extension,null];}$low=$minimum;$high=$preferred;$best=null;$bestQuality=$minimum;for($attempt=0;$attempt<5&&$low<=$high;$attempt++){$quality=$attempt===0?$preferred:(int)floor(($low+$high)/2);[$bytes,$outMime,$extension]=$this->encode($image,$mime,$quality);if(strlen($bytes)<=$target){$best=[$bytes,$outMime,$extension];$bestQuality=$quality;$low=$quality+1;}else{$high=$quality-1;}}if(!$best){[$bytes,$outMime,$extension]=$this->encode($image,$mime,$minimum);$best=[$bytes,$outMime,$extension];$bestQuality=$minimum;}return[...$best,$bestQuality];}
 private function profile(?string$mode):array{return config('media.processing.profiles.'.($mode===MediaQuality::HIGH_RESOLUTION?'high_resolution':'standard'));}private function fingerprint(?string$mode,array$profile,int$version):string{return hash('sha256',json_encode(['version'=>$version,'mode'=>$mode?:MediaQuality::STANDARD,'profile'=>$profile,'encoder'=>'gd','colour'=>'web-srgb-raster','metadata'=>'delivery-stripped']));}
 private function resize($source,int$max,string$mime):array{$width=imagesx($source);$height=imagesy($source);$scale=min(1,$max/max($width,$height));$tw=max(1,(int)round($width*$scale));$th=max(1,(int)round($height*$scale));$target=imagecreatetruecolor($tw,$th);if(in_array($mime,['image/png','image/webp'],true)){imagealphablending($target,false);imagesavealpha($target,true);imagefill($target,0,0,imagecolorallocatealpha($target,0,0,0,127));}imagecopyresampled($target,$source,0,0,0,0,$tw,$th,$width,$height);return[$target,$tw,$th];}
 private function encode($image,string$mime,int$quality):array{ob_start();if($mime==='image/png'){imagepng($image,null,6);$extension='png';}elseif($mime==='image/webp'&&function_exists('imagewebp')){imagewebp($image,null,$quality);$extension='webp';}else{imageinterlace($image,true);imagejpeg($image,null,$quality);$mime='image/jpeg';$extension='jpg';}return[(string)ob_get_clean(),$mime,$extension];}private function orient($image,int$orientation){return match($orientation){3=>imagerotate($image,180,0),6=>imagerotate($image,-90,0),8=>imagerotate($image,90,0),default=>$image};}private function read(string$key):string{if(!$this->storage->exists($key))throw new RuntimeException('Source media is unavailable.');$stream=$this->storage->readStream($key);$bytes=stream_get_contents($stream);fclose($stream);return(string)$bytes;}
}
